export function serverlessInvocation(model: ListedModel) {
  if (
    model.kind !== 'serverless' ||
    model.id !== 'mistral-small-3.2-24b-instruct-2506' ||
    /retired|end_of_life|eol/.test(model.status ?? '')
  )
    return undefined;
  return {
    modelId: model.id,
    maxOutputTokens: 2048,
    source: 'evidence/validation/strands-live-smoke-v1.json',
    protocol: 'chat-completions-sse' as const,
  };
}
